WITH with_gaps AS (SELECT *, CASE WHEN reading_ts - LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts, id) > INTERVAL '1' HOUR THEN 1 ELSE 0 END AS is_new_burst FROM device_readings), sessionized AS (SELECT id, device_code, reading_ts, temp_c, humidity, pressure, firmware, SUM(is_new_burst) OVER (PARTITION BY device_code ORDER BY reading_ts, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS burst_id FROM with_gaps) SELECT burst_id, device_code, ROUND(SUM(temp_c) / NULLIF(COUNT(CASE WHEN device_code = 'DV-01' THEN 1 END), 0), 2) AS temp_c_per_dv_01, SUM(CASE WHEN device_code = 'DV-01' THEN burst_id ELSE 0 END) AS dv_01_burst_id, (UNIX_TIMESTAMP(MAX(reading_ts)) - UNIX_TIMESTAMP(MIN(reading_ts))) / 60 AS duration_min, SIZE(COLLECT_SET(device_code)) AS num_device_codes, SUM(CASE WHEN device_code = 'DV-03' THEN temp_c ELSE 0 END) AS dv_03_temp_c, MAX(pressure) AS max_pressure, GROUPING_ID() AS gid FROM sessionized GROUP BY CUBE (burst_id, device_code) ORDER BY temp_c_per_dv_01
